//! 🕸️ Geometry scalar pages reuse first-party funded list reserve, place and return operations.
use super::{PreparationTurn,PreparationPhase};
use semio_framework_value::retirement::RetireOwned;
use semio_framework_value::{RetireOwned,RetirementDemand,retained_clone::RetainedCloneProgress};
use semio_framework_value_paged_list::PagedList;
const MAXIMUM:usize=u32::MAX as usize;
pub trait MeshScalar:Copy+RetireOwned{fn valid(self)->bool;}
impl MeshScalar for f64{fn valid(self)->bool{self.is_finite()}}
impl MeshScalar for u32{fn valid(self)->bool{true}}
#[derive(RetireOwned)]
pub struct RetainedMeshPages<T:MeshScalar>{values:PagedList<[T;3],MAXIMUM>,maximum:usize,byte_limit:usize,phase:PreparationPhase,identity:Option<super::PreparationIdentity>,work:usize}
impl<T:MeshScalar> RetainedMeshPages<T>{
 pub fn new(maximum:usize,byte_limit:usize)->Result<Self,&'static str>{if maximum>MAXIMUM{return Err("mesh-pages-invalid-limit")}Ok(Self{values:PagedList::empty(),maximum,byte_limit,phase:PreparationPhase::Projecting,identity:None,work:0})}
 pub fn len(&self)->usize{self.values.len()}pub fn allocated_bytes(&self)->usize{self.values.allocated_bytes()}pub fn work(&self)->usize{self.work}
 fn enter(&mut self,turn:&mut PreparationTurn<'_,'_>,demand:RetirementDemand)->Result<bool,&'static str>{turn.cx.original_source_parent().map_err(|_|"mesh-pages-requires-original-source")?;if turn.identity.operation!=turn.cx.operation().0||turn.identity.generation!=turn.cx.generation().0||self.identity.is_some_and(|identity|identity!=*turn.identity){return Err("mesh-pages-original-caller-changed")}if turn.cx.is_cancelled()&&self.phase!=PreparationPhase::Closing{self.phase=PreparationPhase::Cancelling;return Ok(false)}if turn.cx.fuel_remaining()==0||(if self.phase==PreparationPhase::Closing{turn.cx.retirement_should_yield()}else{turn.cx.should_yield()})||!turn.cx.retained_work_can_enter(demand){return Ok(false)}turn.cx.consume_fuel(1);self.work+=1;if self.identity.is_none()&&self.phase!=PreparationPhase::Closing{self.identity=Some(*turn.identity);}Ok(true)}
 pub fn append(&mut self,value:[T;3],turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{self.append_funded(value,turn,0,usize::MAX)}
 pub fn append_funded(&mut self,value:[T;3],turn:&mut PreparationTurn<'_,'_>,overhead:usize,remaining_bytes:usize)->Result<bool,&'static str>{let overhead=overhead.checked_add(if self.identity.is_none(){std::mem::size_of::<super::PreparationIdentity>()}else{0}).ok_or("mesh-pages-copy-demand")?;if self.phase!=PreparationPhase::Projecting{return Ok(false)}if self.values.len()>=self.maximum{return Err("mesh-pages-item-limit")}if value.iter().any(|value|!value.valid()){return Err("mesh-pages-invalid-value")}if !self.values.has_reserved_slot(){let capacity=self.values.next_allocation_bytes().map_err(|_|"mesh-pages-allocation-demand")?;if capacity>remaining_bytes||self.values.allocated_bytes().checked_add(capacity).is_none_or(|bytes|bytes>self.byte_limit){return Err("mesh-pages-byte-limit")}let demand=RetirementDemand{copy_bytes:self.values.next_reserve_copy_byte_demand().map_err(|_|"mesh-pages-copy-demand")?.checked_add(overhead).ok_or("mesh-pages-copy-demand")?,capacity_bytes:capacity,release_bytes:0,depth:self.values.next_reserve_depth_demand().map_err(|_|"mesh-pages-depth-demand")?};if !self.enter(turn,demand)?{return Ok(false)}let mut grant=turn.cx.retained_grant();grant.maximum_copy_bytes-=overhead;match self.values.reserve_one_funded(grant){Ok(mut receipt)=>{receipt.copied_bytes+=overhead;turn.cx.consume_retained(receipt).map_err(|_|"mesh-pages-original-receipt")?;return Ok(false)},Err(error)=>{turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:overhead,retained_capacity_bytes:error.allocated_bytes,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;return Err("mesh-pages-allocation-refused")}}}let copy=std::mem::size_of::<[T;3]>().checked_add(overhead).ok_or("mesh-pages-copy-demand")?;let demand=RetirementDemand{copy_bytes:copy,capacity_bytes:0,release_bytes:0,depth:self.values.next_push_depth_demand().map_err(|_|"mesh-pages-depth-demand")?};if !self.enter(turn,demand)?{return Ok(false)}self.values.push_reserved(value).map_err(|_|"mesh-pages-reserved-slot-lost")?;turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;Ok(true)}
 pub fn truncate_one(&mut self,length:usize,turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{if self.phase!=PreparationPhase::Projecting{return Err("mesh-pages-no-longer-owned")}if length>self.values.len(){return Err("mesh-pages-index")}if length==self.values.len(){return Ok(true)}let copy=std::mem::size_of::<[T;3]>();let demand=RetirementDemand{copy_bytes:copy,depth:self.values.next_pop_depth_demand().map_err(|_|"mesh-pages-depth-demand")?,..Default::default()};if self.enter(turn,demand)?{self.values.pop();turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;}Ok(length==self.values.len())}
 pub fn get(&self,index:usize,axis:usize)->Result<T,&'static str>{if self.phase!=PreparationPhase::Projecting{return Err("mesh-pages-no-longer-owned")}self.values.get(index).and_then(|value|value.get(axis)).copied().ok_or("mesh-pages-index")}
 pub fn begin_close(&mut self){if self.phase!=PreparationPhase::Closed{self.phase=PreparationPhase::Closing}}
 pub fn close(&mut self,turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{if self.phase==PreparationPhase::Closed{return Ok(true)}if self.phase!=PreparationPhase::Closing{return Err("mesh-pages-close-not-started")}if !self.values.is_empty(){let copy=std::mem::size_of::<[T;3]>();let demand=RetirementDemand{copy_bytes:copy,capacity_bytes:0,release_bytes:0,depth:self.values.next_pop_depth_demand().map_err(|_|"mesh-pages-depth-demand")?};if self.enter(turn,demand)?{self.values.pop();turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;}return Ok(false)}if !self.values.terminal_is_empty(){let release=self.values.next_release_allocation_bytes().map_err(|_|"mesh-pages-release-demand")?;let demand=RetirementDemand{copy_bytes:0,capacity_bytes:0,release_bytes:release,depth:self.values.next_release_depth_demand().map_err(|_|"mesh-pages-depth-demand")?};if self.enter(turn,demand)?{let progress=self.values.release_empty_page(turn.cx.retained_grant().maximum_release_bytes).map_err(|_|"mesh-pages-return-refused")?;turn.cx.consume_retained(RetainedCloneProgress{copied_items:usize::from(progress.progressed),released_bytes:progress.released_allocation_bytes,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;}return Ok(false)}if self.enter(turn,RetirementDemand{depth:1,..Default::default()})?{turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}).map_err(|_|"mesh-pages-original-receipt")?;self.phase=PreparationPhase::Closed;self.identity=None;}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.phase==PreparationPhase::Closed&&self.values.terminal_is_empty()}
}

#[cfg(test)]#[path="🧪️tests/🦀️.rs"]mod tests;
